import java.util.EnumMap;
import java.util.EnumSet;

public enum TransactionState {
    INITIATED {
        @Override
        public TransactionState next() { return PENDING; }
    },
    PENDING {
        @Override
        public TransactionState next() { return COMPLETED; }
    },
    COMPLETED {
        @Override
        public TransactionState next() { return COMPLETED; }
    },
    FAILED {
        @Override
        public TransactionState next() { return FAILED; }
    };

    // Abstract method to force constant-specific state transitions
    public abstract TransactionState next();

    // Fields and constructors are fully supported
    private final boolean isTerminal;

    // Constructor is implicitly private
    TransactionState() {
        this.isTerminal = (this.name().equals("COMPLETED") || this.name().equals("FAILED"));
    }

    public boolean isTerminal() {
        return this.isTerminal;
    }

    // Cached array to avoid the values() allocation overhead in hot paths
    private static final TransactionState[] CACHED_VALUES = TransactionState.values();

    public static TransactionState[] getCachedValues() {
        return CACHED_VALUES;
    }

    public static void main(String[] args) {
        // 1. Utilizing EnumSet for high-performance set operations
        EnumSet<TransactionState> activeStates = EnumSet.of(INITIATED, PENDING);
        EnumSet<TransactionState> terminalStates = EnumSet.complementOf(activeStates);

        // 2. Utilizing EnumMap for high-performance, collision-free mappings
        EnumMap<TransactionState, String> stateDescriptions = new EnumMap<>(TransactionState.class);
        stateDescriptions.put(INITIATED, "Transaction has been created but not processed.");
        stateDescriptions.put(PENDING, "Transaction is currently processing in the gateway.");

        System.out.println("Is INITIATED active? " + activeStates.contains(INITIATED));
        System.out.println("Terminal states: " + terminalStates);
        System.out.println("Pending description: " + stateDescriptions.get(PENDING));
    }
}
